using System; using System.Data;
namespace WebApplication7 { public partial class ViewArt : System.Web.UI.Page { private int ArtId { get { int id; return int.TryParse(Request.QueryString["id"], out id) ? id : 0; } } protected void Page_Load(object sender, EventArgs e) { if(!IsPostBack) LoadArt(); } private void LoadArt(){ DataRow r=Database.GetArtwork(ArtId); if(r==null){ Response.Redirect("Gallery.aspx"); return; } imgArt.ImageUrl=r["ImageUrl"].ToString(); imgArt.AlternateText=r["Title"].ToString(); lblTitle.Text=Server.HtmlEncode(r["Title"].ToString()); lblArtist.Text=Server.HtmlEncode(r["Artist"].ToString()); lblCategory.Text=Server.HtmlEncode(r["Category"].ToString()); lblDescription.Text=Server.HtmlEncode(r["Description"].ToString()); lblMedium.Text=Server.HtmlEncode(r["Medium"].ToString()); lblSize.Text=Server.HtmlEncode(r["Size"].ToString()); lblPrice.Text=Convert.ToDecimal(r["Price"]).ToString("N2"); } private bool RequireUser(){ if(Session["UserId"]==null){ Response.Redirect("UserLogin.aspx?returnUrl=ViewArt.aspx%3Fid%3D"+ArtId); return false;} return true;} protected void btnCart_Click(object sender,EventArgs e){ if(RequireUser()){ Database.AddToCart(Convert.ToInt32(Session["UserId"]),ArtId); lblMessage.Text="Painting added to your cart."; } } protected void btnFav_Click(object sender,EventArgs e){ if(RequireUser()){ Database.ToggleFavorite(Convert.ToInt32(Session["UserId"]),ArtId); lblMessage.Text=Database.IsFavorite(Convert.ToInt32(Session["UserId"]),ArtId)?"Added to favorites.":"Removed from favorites."; } } } }